<?php

declare(strict_types=1);require_once __DIR__.'/../../configuracion/inicializacion.php';require_once __DIR__.'/../../controladores/sunat/ControladorLiquidacion.php';require_once __DIR__.'/../../servicios/FiltroPeriodo.php';require_once __DIR__.'/../../servicios/clientes/BusquedaClientes.php';asesconExigirPermiso($conexion,'LIQUIDACIONES','ver');$moduloActivo='LIQUIDACIONES';$periodo=FiltroPeriodo::normalizar((string)($_GET['periodo']??date('Ym')));$datos=(new ControladorLiquidacion($conexion))->datos($periodo);extract($datos);$q=BusquedaClientes::normalizar((string)($_GET['q']??''));
$modo=in_array((string)($_GET['modo']??''),['pagar','favor'],true)?(string)$_GET['modo']:'';
                                                                                 
if(substr($periodo,4,2)!=='00'){
    $conLiquidacion=array_fill_keys(array_map(static fn(array $d):int=>(int)$d['id_cliente'],$filas),true);
    foreach($filas as &$guardada)$guardada['hay_liquidacion']=true;unset($guardada);
    foreach($clientes as $cliente){if(isset($conLiquidacion[(int)$cliente['id_cliente']]))continue;
        $filas[]=array_merge($cliente,['periodo'=>$periodo,'estado'=>'SIN_PREPARAR','hay_liquidacion'=>false,'impuesto_resultado_mostrar'=>null,'saldo_anterior_mostrar'=>null,'credito_fiscal_anterior_mostrar'=>null,'igv_pagar_sf_mostrar'=>null]);
    }
}
$esAnual=substr($periodo,4,2)==='00';
$importeLiquidacion=static fn(array $d,string $campo):string=>$d[$campo]===null?'—':'S/ '.number_format((float)$d[$campo],2);
$filasBusqueda=array_values(array_filter($filas,static fn(array $d):bool=>BusquedaClientes::coincide($d,$q)));
$clientesCoincidentes=array_values(array_filter($clientes,static fn(array $d):bool=>BusquedaClientes::coincide($d,$q)));
$filas=array_values(array_filter($filasBusqueda,static function(array $d)use($modo):bool{
    $valor=(float)($d['igv_pagar_sf_mostrar']??0);
    return $modo==='pagar'?$valor>0:($modo==='favor'?$valor<0:true);
}));
$mensajeVacio='No hay liquidaciones guardadas para el período seleccionado.';
if($q!==''&&$clientesCoincidentes===[]&&$filasBusqueda===[]){$mensajeVacio='No se encontraron clientes visibles con ese nombre o RUC.';}
elseif($q!==''&&$filasBusqueda===[]){$mensajeVacio='El cliente coincide con la búsqueda, pero no tiene una liquidación guardada para este período.';}
elseif($filasBusqueda!==[]&&$filas===[]){$mensajeVacio='No hay liquidaciones que coincidan con el filtro de saldo seleccionado.';}
$anio=(int)substr($periodo,0,4);$mes=(int)substr($periodo,4,2);$meses=[1=>'Enero',2=>'Febrero',3=>'Marzo',4=>'Abril',5=>'Mayo',6=>'Junio',7=>'Julio',8=>'Agosto',9=>'Septiembre',10=>'Octubre',11=>'Noviembre',12=>'Diciembre'];?>
