   <label class="reference-field"><span>Mes</span><select id="liqMes"><option value="00" <?= $mes===0?'selected':'' ?>>Todos los meses / Anual</option>
    <?php foreach($meses as $n=>$nom): ?><option value="<?= str_pad((string)$n,2,'0',STR_PAD_LEFT) ?>" <?= $mes===$n?'selected':'' ?>><?= htmlspecialchars($nom) ?></option><?php endforeach; ?></select></label>
   <label class="reference-field"><span>Año</span><select id="liqAnio">
    <?php for($y=(int)PeriodosSire::ahoraPeru()->format('Y');$y>=2021;$y--): ?><option value="<?= $y ?>" <?= $anio===$y?'selected':'' ?>><?= $y ?></option><?php endfor; ?></select></label>
