   <a class="reference-btn" target="_blank" rel="noopener noreferrer" href="<?= htmlspecialchars(asesconUrl('api/sunat/exportar_liquidacion.php').'?'.http_build_query(['periodo'=>$periodo,'q'=>$q,'modo'=>$modo,'formato'=>'pdf'])) ?>">⇩ PDF guardado</a>
  </div>
 </form>
</section>
